const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.FeatureCollection("USDOS/LSIB_SIMPLE/2017")
                     .filter(ee.Filter.eq('country_na', 'Puerto Rico'))
                     .geometry();
  const date1 = '2016-09-21';
  const date2 = '2016-09-22';
  const collectionName = 'NOAA/VIIRS/DNB/DAILY';
  const bandName = 'avg_rad';

  // 2. Data Acquisition
  const col1 = ee.ImageCollection(collectionName)
                 .filterDate(date1, ee.Date(date1).advance(1, 'day'))
                 .filterBounds(geometry);

  const col2 = ee.ImageCollection(collectionName)
                 .filterDate(date2, ee.Date(date2).advance(1, 'day'))
                 .filterBounds(geometry);

  // 3. Data Availability Check
  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  if (size1 === 0 || size2 === 0) {
    console.log(`Image count for ${date1}: ${size1}`);
    console.log(`Image count for ${date2}: ${size2}`);
    console.log("No images found for one or both dates.");
    console.log("A"); // The daily VIIRS collection can be sparse. It is expected there may not be an overpass.
    return;
  }
  console.log(`Image count for ${date1}: ${size1}`);
  console.log(`Image count for ${date2}: ${size2}`);

  // Mosaic collections to get single images for each date
  const image1 = col1.select(bandName).mosaic().clip(geometry);
  const image2 = col2.select(bandName).mosaic().clip(geometry);

  // 4. Processing & Calculation
  const scale = 1000; // Use a coarser scale to ensure calculation completes
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats1 = image1.reduceRegion({
    reducer: reducer,
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  });

  const stats2 = image2.reduceRegion({
    reducer: reducer,
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  });

  const mean1 = stats1.get(bandName + '_mean').getInfo();
  const count1 = stats1.get(bandName + '_count').getInfo();
  const mean2 = stats2.get(bandName + '_mean').getInfo();
  const count2 = stats2.get(bandName + '_count').getInfo();

  // 5. Validation & Final Answer
  if (count1 === 0 || count2 === 0) {
    console.log(`Valid pixels on ${date1}: ${count1}`);
    console.log(`Valid pixels on ${date2}: ${count2}`);
    console.log("No valid pixels in the region for one or both dates after processing.");
    console.log("C2");
    return;
  }
  console.log(`Valid pixels on ${date1}: ${count1}`);
  console.log(`Valid pixels on ${date2}: ${count2}`);

  if (mean1 === null || mean2 === null) {
    console.log(`Mean light intensity on ${date1}: ${mean1}`);
    console.log(`Mean light intensity on ${date2}: ${mean2}`);
    console.log("Calculation failed, resulting in a null value.");
    console.log("C3");
    return;
  }

  console.log(`Mean Light Intensity on ${date1}: ${mean1.toFixed(4)}`);
  console.log(`Mean Light Intensity on ${date2}: ${mean2.toFixed(4)}`);

  if (mean2 < mean1) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(e);
    console.log("D");
  }
}

initEE();
